dataTransform.transform:
/*DATA TRANSFORM*/
/*This takes all of the inventoryLines and if any of them are on master it will will aggergate them into 
one row. That way you can NOT just remove a single container from a pick leaving the other containers on a master staged.
This will also leave single containers that are not par tof a master
*/
(
  $nonMaster := [edges.node[$isNil(inventory.masterInventoryId)]];
  $masters := $groupBy([edges.node], $path(?, ["inventory", "masterInventoryId"]))
    ~>$values
    ~>$map(function($v){
      {
        "id": $first($v.inventory.masterInventoryId),
        "inventory":{
          "inventoryStatusId": $first($v.inventory.inventoryStatusId),
          "number": $first($v.inventory.masterInventory.number),
          "product":{
            "code": $join($uniq($v.inventory.product.code), " / ")
          },
          "quantity": {"value": $sum($v.inventory.quantity.value) }
        }
      }
    });

    [$masters, $nonMaster]
)
